<template>
  <q-page class="page"><div class="row items-end justify-between q-mb-lg"><div><div class="eyebrow">ADMINISTRATION</div><h1>{{ title }}</h1><p class="muted">Manage reference data used across the banking system.</p></div><q-btn color="primary" icon="add" label="New record" @click="openCreate" /></div>
    <q-table flat bordered :rows="rows" :columns="columns" row-key="id" :loading="loading" no-data-label="No records found"><template #body-cell-actions="props"><q-td :props="props"><q-btn flat round dense icon="edit" color="primary" @click="openEdit(props.row)" /><q-btn flat round dense icon="delete" color="negative" @click="removeRow(props.row)" /></q-td></template></q-table>
    <q-dialog v-model="dialog"><q-card class="form-card"><q-card-section><div class="text-h6">{{ editingId ? 'Edit' : 'New' }} {{ title }}</div></q-card-section><q-card-section><q-form class="q-gutter-md" @submit="save"><template v-if="resource === 'roles'"><q-input v-model="form.role_code" label="Role code" outlined /><q-input v-model="form.role_name" label="Role name" outlined /><q-input v-model="form.description" label="Description" type="textarea" outlined /></template><template v-else-if="resource === 'accountTypes'"><q-input v-model="form.type_code" label="Type code" outlined /><q-input v-model="form.type_name" label="Type name" outlined /><q-input v-for="field in numericFields" :key="field" v-model.number="form[field]" :label="label(field)" type="number" step="0.01" outlined /></template><template v-else-if="resource === 'banks'"><q-input v-model="form.bank_code" label="Bank code" outlined /><q-input v-model="form.bank_name" label="Bank name" outlined /><q-input v-model="form.swift_code" label="SWIFT code" outlined /><q-input v-model="form.short_name" label="Short name" outlined /><q-input v-model="form.api_endpoint" label="API endpoint" outlined /><q-input v-model="form.contact_email" label="Contact email" type="email" outlined /><q-select v-model="form.status" label="Status" :options="['ACTIVE', 'INACTIVE']" outlined /></template><template v-else><q-input v-model="form.fee_code" label="Fee code" outlined /><q-input v-model="form.fee_name" label="Fee name" outlined /><q-input v-model="form.fee_description" label="Description" type="textarea" outlined /><q-input v-model.number="form.fixed_amount" label="Fixed amount" type="number" step="0.01" outlined /><q-input v-model.number="form.percentage_rate" label="Percentage rate" type="number" step="0.01" outlined /></template><div class="row justify-end q-gutter-sm"><q-btn flat label="Cancel" v-close-popup /><q-btn color="primary" label="Save" type="submit" :loading="saving" /></div></q-form></q-card-section></q-card></q-dialog>
  </q-page>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { useQuasar } from 'quasar'; import api from 'src/services/api'
const route = useRoute(); const $q = useQuasar(); const title = computed(() => route.meta.title); const resource = computed(() => route.meta.resource); const endpoint = computed(() => route.meta.endpoint); const rows = ref([]); const loading = ref(false); const saving = ref(false); const dialog = ref(false); const editingId = ref(null); const numericFields = ['minimum_balance', 'opening_deposit', 'annual_interest_rate', 'daily_withdrawal_limit']; const form = ref({})
const columns = computed(() => { const sample = rows.value[0] || ({ id: 0, role_code: '', role_name: '', description: '', created_at: '' }); return Object.keys(sample).filter((key) => key !== 'id').map((name) => ({ name, label: name.replaceAll('_', ' ').toUpperCase(), field: name, align: 'left' })).concat([{ name: 'actions', label: '', field: 'actions', align: 'right' }]) })
function blank () { return resource.value === 'roles' ? { role_code: '', role_name: '', description: '' } : resource.value === 'accountTypes' ? { type_code: '', type_name: '', minimum_balance: 0, opening_deposit: 0, annual_interest_rate: 0, daily_withdrawal_limit: 0 } : resource.value === 'banks' ? { bank_code: '', bank_name: '', swift_code: '', short_name: '', api_endpoint: '', contact_email: '', status: 'ACTIVE' } : { fee_code: '', fee_name: '', fee_description: '', fixed_amount: 0, percentage_rate: 0 } }
function label (field) { return field.replaceAll('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase()) }
async function loadRows () { loading.value = true; try { rows.value = (await api.get(endpoint.value)).data } catch (error) { $q.notify({ type: 'negative', message: error.response?.data?.detail || 'Could not load records' }) } finally { loading.value = false } }
function openCreate () { editingId.value = null; form.value = blank(); dialog.value = true }
function openEdit (row) { editingId.value = row.id; form.value = { ...row }; dialog.value = true }
async function save () { saving.value = true; try { if (editingId.value) await api.put(`${endpoint.value}${editingId.value}`, form.value); else await api.post(endpoint.value, form.value); dialog.value = false; $q.notify({ type: 'positive', message: 'Saved successfully' }); await loadRows() } catch (error) { $q.notify({ type: 'negative', message: error.response?.data?.detail || 'Could not save record' }) } finally { saving.value = false } }
function removeRow (row) { $q.dialog({ title: 'Confirm delete', message: `Delete record #${row.id}?`, cancel: true }).onOk(async () => { try { await api.delete(`${endpoint.value}${row.id}`); await loadRows(); $q.notify({ type: 'positive', message: 'Deleted' }) } catch (error) { $q.notify({ type: 'negative', message: error.response?.data?.detail || 'Could not delete record' }) } }) }
onMounted(loadRows)
</script>
